SELECT p.gender, s.age, s.exacerbation, s.composite_risk_score, q.quartile, COUNT(DISTINCT CASE WHEN s.deathtime IS NOT NULL THEN s.subject_id END) AS mortality_count, COUNT(DISTINCT CASE WHEN s.exacerbation = 'Major' THEN s.subject_id END) AS major_complication_count, AVG(s.los) AS average_los, SUM(CASE WHEN p.gender = 'F' AND s.age BETWEEN 75 AND 85 THEN 1 ELSE 0 END) AS subquery_count FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN stay s ON a.stay_id = s.stay_id JOIN quartiles q ON s.composite_risk_score BETWEEN q.lower_bound AND q.upper_bound WHERE p.age = 80 AND s.exacerbation = 'Exacerbation' GROUP BY p.gender, s.age, s.exacerbation, q.quartile ORDER BY q.quartile, mortality_count, major_complication_count, average_los NULLS LAST;